export type LogoName = keyof typeof logos;

/**
 * A brand mark by name. Decorative unless given an aria-label. Each drawing's ids (gradients, masks,
 * filters: all "lg-<name>-…") are made unique to it, so a mark never paints with another copy's
 * definitions, which don't render while that copy is hidden.
 */
export function Logo({
  name,
  ...props
}: { name: LogoName } & Omit<SVGProps<SVGSVGElement>, "name">) {
  const { viewBox, inner } = logos[name];
  const label = props["aria-label"];
  const uid = useId().replaceAll(/[^\w-]/g, "");
  const html = inner.replaceAll(`lg-${name}-`, `lg-${name}-${uid}-`);
  return (
    <svg
      viewBox={viewBox}
      xmlns="http://www.w3.org/2000/svg"
      fill={name.endsWith("-mono") ? "currentColor" : undefined}
      role={label ? "img" : undefined}
      aria-hidden={label ? undefined : true}
      focusable="false"
      {...props}
      // biome-ignore lint/security/noDangerouslySetInnerHtml: fixed, first-party SVG markup from this file.
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
